const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={case:0,selection:null,scope:0},view={x:0,y:0,s:1};let c,m,scopes=[],height=600;const svg=$('workspace');
const text=(x,y,t,size=12,color='#bbb')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${color}">${esc(t)}</text>`;
function lines(x,y,s,width=46){const words=String(s||'—').match(new RegExp('.{1,'+width+'}','g'))||[];return words.slice(0,5).map((w,i)=>text(x,y+i*18,w)).join('');}
function payload(){return SyncModel.context(c,m,state.selection,$('question').value)}
