function selectFinding(id){const f=m.findings.find(f=>f.id===id);if(!f)return;state.selection=f;const near=[...m.objects].sort((a,b)=>Math.abs(a.line-f.line)-Math.abs(b.line-f.line))[0];if(near)state.scope=Math.max(0,scopes.indexOf(near.func));$('question').value=`请核对 ${c.file}:${f.line} 的 ${f.code} 候选：${f.message}。追踪关联文件、条件路径及 API 语义，给出最小验证与修改方案。`;render();openPanel('inspector');}
function selectObject(id){state.selection=m.objects.find(o=>o.type+':'+o.id===id);$('question').value=`请核对 ${c.file}:${state.selection.line} 的 ${state.selection.label} 及其静态关联关系。`;render();openPanel('inspector');}
function openPanel(id){const p=$(id);p.hidden=false;p.style.left='auto';p.style.right=innerWidth<600?'16px':'26px';p.style.top=innerWidth<1000?'136px':'86px';p.style.height='auto';if(id==='sourcePanel')sourcePosition();syncButtons();}
function sourcePosition(){$('sourceCode').scrollTop=Math.max(0,((state.selection?.line||1)-8)*18.7)}
function syncButtons(){for(const [b,p]of [['auditToggle','inspector'],['evidenceToggle','inspector'],['sourceToggle','sourcePanel'],['infoToggle','info']])$(b).setAttribute('aria-expanded',String(!$(p).hidden));}
function render(){
 $('identity').textContent=c.file+' · '+c.revision.slice(0,10);$('caseTrigger').textContent=c.label+' ▾';$('caseMenu').innerHTML=DATA.cases.map((x,i)=>`<button data-case="${i}" aria-pressed="${state.case===i}" data-tip="打开 ${esc(x.label)} 的扫描证据">${esc(x.label)}</button>`).join('');
 const fn=scopes[state.scope];const objects=m.objects.filter(o=>o.func===fn);const left=objects.filter(o=>o.type!=='sync'),right=objects.filter(o=>o.type==='sync');const pos=new Map();left.forEach((o,i)=>pos.set(o.type+':'+o.id,{x:60,y:110+i*210,w:o.type==='access'?408:400}));right.forEach((o,i)=>pos.set(o.type+':'+o.id,{x:800,y:110+i*155,w:300}));height=Math.max(470,150+Math.max(left.length*210,right.length*155));
 let body=text(60,45,fn||'未提取函数',24,'#eee')+text(60,72,'BUFFER ACCESS / SOURCE OPERATION',11)+text(800,72,'SYNC',11);
 const related=new Set(state.selection?.scanner?SyncModel.related(m,state.selection):state.selection?[state.selection.type+':'+state.selection.id]:[]);
 for(const relation of m.relations){const a=pos.get(relation.from),b=pos.get(relation.to);if(!a||!b)continue;const color=relation.status==='covered'?'#888':'#d8ae73';body+=`<path d="M${a.x+a.w} ${a.y+32} H630 V${b.y+32} H${relation.type==='dependency'?b.x+b.w:b.x}" fill="none" stroke="${color}" stroke-width="1.4" stroke-dasharray="${relation.status==='covered'?'2 5':'6 4'}"/><circle cx="${relation.type==='dependency'?b.x+b.w:b.x}" cy="${b.y+32}" r="3" fill="${color}"/>`+text(490,a.y+20,relation.id+' · '+relation.status,10,color);}
 for(const o of objects){const id=o.type+':'+o.id,p=pos.get(id),selected=state.selection?.id===o.id&&!state.selection?.scanner,linked=related.has(id),fill=selected?'#B1EF6B':linked?'#2f3529':'#1c1c1c';body+=`<g role="button" tabindex="0" data-object-key="${id}" aria-label="${esc(o.label)}，${esc(o.type)}，源码第 ${o.line} 行" data-tip="${esc(o.raw)}">`;
 if(o.type==='access'){body+=`<rect x="${p.x-8}" y="${p.y-8}" width="416" height="182" rx="8" fill="${fill}"/>`+VisualSystem.node('memref',o.id,o.id+' · '+o.access,p.x,p.y)+text(p.x+196,p.y+20,'L'+o.line+' · '+(o.pipe||'source'),11,selected?'#111':'#aaa')+lines(p.x,p.y+86,o.buffer.name,45)+lines(p.x,p.y+110,o.buffer.index_expr,45)+text(p.x,p.y+162,'root · '+o.root,11,selected?'#111':'#bbb');}
 else{body+=`<rect x="${p.x}" y="${p.y}" width="${p.w}" height="110" rx="8" fill="${fill}"/>`+text(p.x+14,p.y+23,o.label,14,selected?'#111':'#ddd')+text(p.x+14,p.y+45,'L'+o.line+' · '+o.id,11,selected?'#111':'#aaa')+lines(p.x+14,p.y+68,o.flag_id||o.raw,o.type==='sync'?32:46);}
 body+='</g>';}
 if(!objects.length)body+=text(60,150,'此文件未提取到图对象；原始扫描结果仍可核对。',14);
 $('world').innerHTML=body;$('range').textContent=(state.scope+1)+' / '+scopes.length+' · '+(fn||'—');$('prev').disabled=state.scope===0;$('next').disabled=state.scope===scopes.length-1;
 $('counts').textContent=`结构扫描 ${c.audit.findings.length} · 图分析 ${c.graph.findings.length} · 正则前端`;
 $('findings').innerHTML=m.findings.length?m.findings.map(f=>`<button class="finding" data-finding="${f.id}" aria-current="${state.selection?.id===f.id}" data-tip="定位源码第 ${f.line} 行及关联图证据">${esc(f.code)} · ${esc(f.severity)} · L${f.line}<br>${esc(f.message)}<small>${f.scanner}</small></button>`).join(''):'<p>两套扫描器在当前文件均无候选；覆盖范围见 Info。</p>';
 const f=state.selection;const ev=f?.evidence||{};const row=(a,b)=>`<tr><td>${esc(a)}</td><td>${esc(b)}</td></tr>`;
 $('detail').innerHTML=f?`<h3>${esc(f.code||f.label)} · L${f.line}</h3><p>${esc(f.message||f.raw)}</p><table>${Object.entries({producer:ev.bad_operation?ev.bad_operation.id+' · L'+ev.bad_operation.line:ev.buffer_dependencies?.[0]?.producer_access_id,consumer:ev.buffer_dependencies?.[0]?.consumer_access_id||'未在此证据链确认',buffer_access:ev.buffer_access?ev.buffer_access.id+' · L'+ev.buffer_access.line:undefined,sync_edge:ev.sync_edge?ev.sync_edge.id+' · L'+ev.sync_edge.line:undefined,sync_coverage:ev.sync_coverage?.status,expected_root:ev.expected_root,actual_root:ev.actual_root,expected_region:ev.expected_region||ev.sync_coverage?.expected_region,actual_region:ev.actual_region||ev.sync_coverage?.actual_region}).filter(([,v])=>v).map(([k,v])=>row(k,v)).join('')}</table><details><summary>完整候选 / 对象证据</summary><pre>${esc(JSON.stringify(f,null,2))}</pre></details>`:'<p>选择访问、同步对象或核查候选。</p>';
 const line=f?.line||1;$('origin').href=c.origin+'#L'+line;$('sourceState').textContent=c.derived?'本地试验副本；链接指向原始上游文件，修改见补丁。':'固定版本源码快照 · '+c.sourceSha256.slice(0,12);$('sourceCode').innerHTML=c.source.split('\n').map((s,i)=>`<span class="source-line${i+1===line?' current':''}">${String(i+1).padStart(4)}  ${esc(s)}</span>`).join('');$('raw').textContent=JSON.stringify({structure:c.audit,flow:c.graph},null,2);$('patch').textContent=c.patch;$('patchDetails').hidden=!c.patch;$('limits').textContent=c.limits.join('；');$('scanner').textContent='CANNBot · '+DATA.scanner.revision.slice(0,12);preview();if(!$('sourcePanel').hidden)sourcePosition();transform();}
function changeCase(i){state.case=i;c=DATA.cases[i];m=SyncModel.model(c);scopes=[...new Set(m.objects.map(o=>o.func))];if(!scopes.length)scopes=[''];state.scope=0;state.selection=null;$('question').value='请基于当前证据核对候选与验证方案。';render();fit();}
function transform(){$('world').setAttribute('transform',`translate(${view.x} ${view.y}) scale(${view.s})`);$('zoom').textContent=Math.round(view.s*100)+'%';}
function fit(){view.s=Math.max(.12,Math.min((innerWidth-90)/1180,(innerHeight-200)/height,1.15));view.x=(innerWidth-1180*view.s)/2;view.y=innerWidth<1000?150:110;transform();}
function zoom(f,x=innerWidth/2,y=innerHeight/2){const old=view.s;view.s=Math.max(.1,Math.min(4,old*f));view.x=x-(x-view.x)*view.s/old;view.y=y-(y-view.y)*view.s/old;transform();}
$('caseTrigger').onclick=()=>{$('caseMenu').hidden=!$('caseMenu').hidden;$('caseTrigger').setAttribute('aria-expanded',String(!$('caseMenu').hidden));if(!$('caseMenu').hidden)$('caseMenu').querySelector('button').focus()};$('caseMenu').onclick=e=>{const b=e.target.closest('[data-case]');if(b){changeCase(+b.dataset.case);$('caseMenu').hidden=true;$('caseTrigger').setAttribute('aria-expanded','false');$('caseTrigger').focus()}};
$('caseMenu').onkeydown=e=>{const a=[...$('caseMenu').querySelectorAll('button')],i=a.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();a[e.key==='Home'?0:e.key==='End'?a.length-1:(i+(e.key==='ArrowDown'?1:-1)+a.length)%a.length].focus()}};
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.configuration')){$('caseMenu').hidden=true;$('caseTrigger').setAttribute('aria-expanded','false')}});
$('prev').onclick=()=>{state.scope=Math.max(0,state.scope-1);render()};$('next').onclick=()=>{state.scope=Math.min(scopes.length-1,state.scope+1);render()};$('findings').onclick=e=>{const b=e.target.closest('[data-finding]');if(b)selectFinding(b.dataset.finding)};
$('world').onclick=e=>{if(moved)return;const o=e.target.closest('[data-object-key]');if(o)selectObject(o.dataset.objectKey)};$('world').onkeydown=e=>{if(['Enter',' '].includes(e.key)){const o=e.target.closest('[data-object-key]');if(o){e.preventDefault();selectObject(o.dataset.objectKey)}}};
$('auditToggle').onclick=()=>openPanel('inspector');$('evidenceToggle').onclick=()=>openPanel('inspector');$('sourceToggle').onclick=()=>openPanel('sourcePanel');$('infoToggle').onclick=()=>openPanel('info');document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{$(b.dataset.close).hidden=true;syncButtons()});$('question').oninput=preview;
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(JSON.stringify(payload(),null,2));$('status').textContent='已复制'}catch{$('status').textContent='复制失败，请从上下文预览手动复制'}};$('download').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(payload(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='sync-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
$('plus').onclick=()=>zoom(1.2);$('minus').onclick=()=>zoom(1/1.2);$('fit').onclick=fit;let drag=null,moved=false;$('canvas').onpointerdown=e=>{if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,ox:view.x,oy:view.y};moved=false};$('canvas').onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>4)moved=true;if(moved){view.x=drag.ox+dx;view.y=drag.oy+dy;transform()}};window.addEventListener('pointerup',()=>{drag=null;setTimeout(()=>moved=false,0)});$('canvas').addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(-e.deltaY*.0015),e.clientX,e.clientY)},{passive:false});window.addEventListener('resize',transform);
for(const head of document.querySelectorAll('.panel .head')){let d;head.onpointerdown=e=>{if(e.target.closest('button'))return;const p=head.parentElement,b=p.getBoundingClientRect();d={x:e.clientX,y:e.clientY,l:b.left,t:b.top};head.setPointerCapture(e.pointerId)};head.onpointermove=e=>{if(!d)return;const p=head.parentElement;p.style.left=Math.max(0,Math.min(innerWidth-180,d.l+e.clientX-d.x))+'px';p.style.top=Math.max(0,Math.min(innerHeight-80,d.t+e.clientY-d.y))+'px';p.style.right='auto'};head.onpointerup=head.onpointercancel=()=>d=null;}
window.addEventListener('keydown',e=>{if(e.key==='Escape'){$('caseMenu').hidden=true;$('caseTrigger').setAttribute('aria-expanded','false');for(const p of ['inspector','sourcePanel','info'])$(p).hidden=true;syncButtons()}});changeCase(0);
